sp_widget.client_script:
api.controller = function($scope, $timeout) {
  $scope.data = {
    status: "⏳ Loading models...",
    modelsLoaded: false,
    name: '',
    email: '',
    phone: '',
    password: ''
  };

  const video = document.getElementById('faceVideo');
  const canvas = document.getElementById('faceCanvas');
  const MODEL_URL = 'https://cdn.jsdelivr.net/npm/face-api.js/weights';

  async function loadModels() {
    await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
    await faceapi.nets.faceLandmark68Net.loadFromUri(MODEL_URL);
    await faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL);

    $scope.$apply(() => {
      $scope.data.modelsLoaded = true;
      $scope.data.status = "✅ Models Loaded. Ready for registration.";
    });

    navigator.mediaDevices.getUserMedia({ video: true }).then(stream => {
      video.srcObject = stream;
    });
  }

  loadModels();

  // Capture and Register Face
  this.registerFace = async function() {
    const detection = await faceapi
      .detectSingleFace(video, new faceapi.TinyFaceDetectorOptions())
      .withFaceLandmarks()
      .withFaceDescriptor();

    if (!detection) {
      $scope.$apply(() => $scope.data.status = "❌ No face detected. Try again.");
      return;
    }

    // Convert Float32Array → normal Array for storage
    const embedding = Array.from(detection.descriptor);

    $scope.data.status = "🔄 Saving user & face embedding...";
    $scope.$apply();

    // Send to server script
    api.server.create({
      name: $scope.data.name,
      email: $scope.data.email,
      phone: $scope.data.phone,
      password: $scope.data.password,
      embedding: embedding
    }).then(() => {
      $scope.data.status = "✅ User registered with face!";
      $scope.$apply();
    });
  };
};

sp_widget.script:
(function() {
  if (input) {
    var gr = new GlideRecord("x_938076_now_utils_face_registry_details");
    gr.initialize();
    gr.u_name = input.name;
    gr.u_email = input.email;
    gr.u_phone = input.phone;
    gr.u_password = input.password;
    gr.u_face_embedding = JSON.stringify(input.embedding);
    gr.insert();

    data.success = true;
  }
})();
